import java.util.*;

public List<String> permutations(String s) {
    char[] chars = s.toCharArray();
    boolean[] used = new boolean[chars.length];
    Set<String> seen = new TreeSet<>();   // TreeSet keeps them sorted + deduped
    backtrack(chars, used, new StringBuilder(), seen);
    return new ArrayList<>(seen);
}

private void backtrack(char[] chars, boolean[] used, StringBuilder path, Set<String> seen) {
    if (path.length() == chars.length) {
        seen.add(path.toString());
        return;
    }
    for (int i = 0; i < chars.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        path.append(chars[i]);
        backtrack(chars, used, path, seen);
        path.deleteCharAt(path.length() - 1);
        used[i] = false;
    }
}

