def permutations(s: str) -> list[str]:
    chars = list(s)
    n = len(chars)
    used = [False] * n
    seen = set()
    path = []

    def backtrack():
        if len(path) == n:
            seen.add(''.join(path))
            return
        for i in range(n):
            if used[i]:
                continue
            used[i] = True
            path.append(chars[i])
            backtrack()
            path.pop()
            used[i] = False

    backtrack()
    return sorted(seen)

