import java.util.*;

public List<String> permutations(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);                       // sort → lexicographic emission
    boolean[] used = new boolean[chars.length];
    List<String> results = new ArrayList<>();
    backtrack(chars, used, new StringBuilder(), results);
    return results;
}

private void backtrack(char[] chars, boolean[] used,
                       StringBuilder path, List<String> results) {
    if (path.length() == chars.length) {
        results.add(path.toString());         // full-length leaf → record
        return;
    }
    for (int i = 0; i < chars.length; i++) {
        if (used[i]) continue;                 // already placed
        if (i > 0 && chars[i] == chars[i - 1] && !used[i - 1]) continue;  // dedup
        used[i] = true;                        // choose
        path.append(chars[i]);
        backtrack(chars, used, path, results); // explore
        path.deleteCharAt(path.length() - 1);  // un-choose: restore BOTH
        used[i] = false;
    }
}

